"""Persistent binary next-token sources generated by the six-input state contrasts."""

import argparse
import json
from decimal import Decimal, localcontext
from fractions import Fraction as F
from pathlib import Path

import numpy as np
import sympy as sp
from learn_state_width import INPUTS
from stochastic_identities import contrast, identities

REGISTRATION = "a92bc31"
SIGNS = np.array([1, -1], dtype=int)
UNITS = np.array([[contrast(p, x) // 4 for x in INPUTS] for p in identities()])
STRENGTHS = (F(1, 4), F(1, 2), F(3, 4))


def entropy_gain(x):
    if not x:
        return 0.0
    with localcontext() as ctx:
        ctx.prec = 75
        z = Decimal(x.numerator) / Decimal(x.denominator)
        return float(((1 + z) * (1 + z).ln() + (1 - z) * (1 - z).ln()) / 2)


def sampled_gain(mass, corr, beta):
    return sum(float(r) * entropy_gain(beta * c / r) for r, c in zip(mass, corr) if r)


def chain(units, beta):
    p = sp.zeros(64)
    for w, v in enumerate(units):
        for bit in range(2):
            nxt = (2 * w + bit) % 64
            p[w, nxt] = (1 + int(SIGNS[bit] * v) * sp.Rational(beta)) / 2
    assert all(x == 1 for x in p * sp.ones(64, 1))
    assert all(x == 1 for x in sp.ones(1, 64) * p)
    return p


def solve(lhs, rhs):
    a, b = lhs.to_DM().unify(rhs.to_DM())
    ans, denom = a.solve_den(b)
    return ans.to_Matrix().applyfunc(lambda x: sp.cancel(x / a.domain.to_sympy(denom)))


def delay_audit(p, beta, sign):
    last = sp.Matrix([1 - 2 * (w % 2) for w in range(64)])
    forward = last
    lags = []
    for _ in range(10):
        forward = p * forward
        lags.append(F(last.dot(forward) / 64))
    assert lags[:6] == [0] * 6 and lags[6] == sign * beta**2 / 8
    records = []
    for weight in (F(1, 100), F(1, 2)):
        amplitude = (1 - weight) / 2
        suffixes = solve(sp.eye(64) - sp.Rational(weight) * p, p * last)
        corr = amplitude * F(last.dot(suffixes) / 64)
        if weight == F(1, 100):
            assert (
                sign * corr
                >= amplitude
                * weight**6
                * beta**2
                * (F(1, 8) - 6 * weight / (1 - weight))
                > 0
            )
        records.append(
            {
                "retention": str(weight),
                "correlation": float(corr),
                "sampled_gain": entropy_gain(corr),
            }
        )
    return {"lags_one_to_ten": list(map(str, lags)), "stochastic_delays": records}


def three_state_stationary(units):
    # A double plus synchronizes. Remaining words need only one unknown conditional mass.
    plus, minus = (1, 2, 2), (0, 1, 0)
    maps = (plus, minus)
    images = []
    for x in INPUTS:
        q = [0, 1, 2]
        for s in x:
            q = [maps[int(s < 0)][v] for v in q]
        images.append(sorted(set(q)))
    unknowns = [i for i, image in enumerate(images) if len(image) == 2]
    assert len(unknowns) == 21 and max(map(len, images)) == 2
    lookup = {w: i for i, w in enumerate(unknowns)}
    beta = sp.Symbol("b")
    lhs, rhs = sp.eye(21), sp.zeros(21, 1)
    for w in unknowns:
        bit, target = w % 2, images[w][0]
        for a in (0, 1):
            prev = (w >> 1) + 32 * a
            weight = (1 + int(SIGNS[bit] * units[prev]) * beta) / 2
            opts = [int(maps[bit][q] == target) for q in images[prev]]
            rhs[lookup[w]] += weight * opts[-1]
            if len(opts) == 2:
                lhs[lookup[w], lookup[prev]] -= weight * (opts[0] - opts[1])
    sol = solve(lhs, rhs)
    assert all(sp.cancel(v) == 0 for v in lhs * sol - rhs)
    joint = sp.zeros(64, 3)
    for w, ids in enumerate(images):
        if len(ids) == 1:
            joint[w, ids[0]] = 1
        else:
            joint[w, ids[0]] = sol[lookup[w]]
            joint[w, ids[1]] = 1 - sol[lookup[w]]
    # Verify the full unreduced stationarity equations against the symbolic result.
    check = sp.zeros(64, 3)
    for w in range(64):
        for bit in (0, 1):
            weight = (1 + int(SIGNS[bit] * units[w]) * beta) / 2
            for q in range(3):
                check[(2 * w + bit) % 64, maps[bit][q]] += joint[w, q] * weight
    assert all(sp.cancel(v) == 0 for v in joint - check)
    mass = (sp.ones(1, 64) * joint / 64).applyfunc(sp.factor)
    corr = (sp.Matrix(units).T * joint / 64).applyfunc(sp.factor)
    assert sp.cancel(corr[2] - beta * (36 - 5 * beta**2) / (64 * (48 - beta**4))) == 0
    report = {
        "plus": plus,
        "minus": minus,
        "uncertain_words": len(unknowns),
        "stationary_masses": list(map(str, mass)),
        "unit_correlations": list(map(str, corr)),
    }
    gains = []
    for s in STRENGTHS:
        weights = [F(v.subs(beta, s)) for v in mass]
        values = [F(v.subs(beta, s)) for v in corr]
        gains.append(sampled_gain(weights, values, s))
    return report, gains


def four_state_stationary(units, beta):
    center = np.array([F(i, 7) for i in (2, 2, 1, 2)])
    eye = np.eye(4, dtype=int)
    maps = [(7 * eye[list(m)] + center) / 8 for m in ((3, 0, 1, 3), (2, 1, 1, 0))]
    # Exact object arithmetic from the first operation.
    maps = [np.array([[F(v) for v in row] for row in mat]) for mat in maps]
    prev = np.array([[(w >> 1) + 32 * a for a in (0, 1)] for w in range(64)])
    bits = np.arange(64) % 2
    rev = (1 + np.array(SIGNS[bits, None] * units[prev], dtype=object) * beta) / 2

    def step(z, weights, kernels):
        before = (weights[:, :, None] * z[prev]).sum(axis=1)
        out = np.empty_like(z)
        for bit in (0, 1):
            out[bit::2] = before[bit::2] @ kernels[bit]
        return out

    z = np.tile(center.astype(float), (64, 1))
    numeric_maps = [k.astype(float) for k in maps]
    weights = rev.astype(float)
    for _ in range(320):
        updated = step(z, weights, numeric_maps)
        if np.max(np.abs(updated - z)) < 4e-16:
            z = updated
            break
        z = updated
    scale = 2**47
    q = np.rint(z[:, :3] * scale).astype(np.int64)
    q = np.column_stack((q, scale - q.sum(axis=1))).astype(object) * F(1, scale)
    assert np.min(q) >= 0
    residual = max(sum(map(abs, row)) for row in q - step(q, rev, maps))
    error = 8 * residual  # contraction at most 7/8 in max over rows of their l1 norm
    assert error < F(1, 10**11)
    mass, corr = q.sum(axis=0) / 64, units @ q / 64
    loss_error = error * beta / (1 - beta)
    return {
        "sampled_gain": sampled_gain(mass, corr, beta),
        "stationary_l1_error_bound": float(error),
        "gain_absolute_error_bound": float(loss_error) + 1e-16,
    }


def exact_width(units):
    successors = (2 * np.arange(64)[:, None] + np.arange(2)) % 64
    _, old = np.unique(units, return_inverse=True)
    sizes = [int(old.max() + 1)]
    while True:
        keys = np.column_stack((old, old[successors]))
        _, new = np.unique(keys, axis=0, return_inverse=True)
        sizes.append(int(new.max() + 1))
        if sizes[-1] == sizes[-2]:
            return sizes
        old = new


def audit():
    out = {}
    for name, units, sign in zip(("first", "second"), UNITS, (1, -1)):
        symbolic, small_gains = three_state_stationary(units)
        records = []
        for beta, three in zip(STRENGTHS, small_gains):
            p = chain(units, beta)
            records.append(
                {
                    "strength": str(beta),
                    "oracle_gain": 3 * entropy_gain(beta) / 8,
                    "three_state_gain": three,
                    "four_state": four_state_stationary(units, beta),
                    **delay_audit(p, beta, sign),
                }
            )
        widths = exact_width(units)
        assert widths[-1] == 36
        out[name] = {
            "three_state_symbolic": symbolic,
            "operating_points": records,
            "continuation_partition_sizes": widths,
        }
    return {"registration": REGISTRATION, "sources": out}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    raw = json.dumps(audit(), indent=2, allow_nan=False) + "\n"
    if args.output:
        args.output.write_bytes(raw.encode())
    else:
        print(raw, end="")
